<script>
import QuickView from "@/components/QuickView.vue";
import axios from "axios";
import { mapState } from "vuex";
export default {
    name: "Menu",

    data() {
        return {
            foodObj: { name: "", category: "", status: [], price: "", type: "" },

            showQuickView: false,
            showDropDown: false,
            sendId: null,

            perPage: 6,
            pageNum: 0,
            previousCategoryClicked: "",
            previousPriceClicked: "",
            previousTypeClicked: "",
            recommendedFoods: [],
            recommendationsLoading: false,
        };
    },

    mounted() {
        this.getRecommendations();
        if (this.$route && this.$route.query && this.$route.query.category) {
            this.applyCategoryFromQuery(this.$route.query.category);
        }
    },

    watch: {
        user() {
            this.getRecommendations();
        },
        '$route.query.category'(newCat) {
            this.applyCategoryFromQuery(newCat);
        }
    },
computed: {
        ...mapState(["allFoods", "user"]),

        filterFoods: function () {
            const queryName = (this.foodObj.name || "").toLowerCase().trim();
            const queryType = (this.foodObj.type || "").toLowerCase().trim();

            return this.allFoods.filter((f) => {
                const foodName = (f.food_name || "").toLowerCase();
                const matchName = !queryName || foodName.includes(queryName);

                const matchCategory = this.matchCategory(f, this.foodObj.category);

                const matchPrice = this.evaluatePrice(f, this.foodObj.price);

                const foodType = (f.food_type || "").toLowerCase();
                const matchType = !queryType || foodType.includes(queryType);

                const matchStatus = this.evaluateStatus(f, this.foodObj.status);

                return matchName && matchCategory && matchPrice && matchType && matchStatus;
            });
        },
        currentPageItems: function () {
            return this.filterFoods.slice(this.pageNum * this.perPage, this.pageNum * this.perPage + this.perPage);
        },
        calculatePages: function () {
            if (this.filterFoods.length % this.perPage != 0) {
                return Math.floor((this.filterFoods.length) / this.perPage) + 1;
            }
            else {
                return this.filterFoods.length / this.perPage;
            }
        }
    },
    methods: {
        applyCategoryFromQuery(category) {
            const queryCat = category ? String(category).toLowerCase().trim() : "all";
            this.foodObj.category = queryCat;
            this.pageNum = 0;
            this.$nextTick(() => {
                if (this.previousCategoryClicked && this.previousCategoryClicked.target) {
                    this.previousCategoryClicked.target.style.background = "#27ae60";
                }
                const btn = document.querySelector(`.menu-tab-item[value="${queryCat}"]`);
                if (btn) {
                    btn.style.background = "#057835fa";
                    this.previousCategoryClicked = { target: btn };
                }
            });
        },
        matchCategory(food, selectedCategory) {
            if (!selectedCategory || selectedCategory === "all") {
                return true;
            }
            const cat = selectedCategory.toLowerCase().trim();
            const foodCat = String(food.food_category || "").toLowerCase().trim();
            const generalCat = String(food.category || "").toLowerCase().trim();
            const cuisine = String(food.cuisine_type || "").toLowerCase().trim();
            const src = String(food.food_src || "").toLowerCase().trim();

            if (cat === "african") {
                return (
                    cuisine === "ivorian" ||
                    cuisine === "west_african" ||
                    cuisine.includes("african") ||
                    foodCat.includes("african") ||
                    generalCat.includes("african") ||
                    src.startsWith("african/")
                );
            }

            if (cat === "fast food") {
                return (
                    cuisine === "american" ||
                    foodCat.includes("fast food") ||
                    generalCat.includes("fast food") ||
                    ["burger", "sandwich", "quick_bite", "wrap", "chicken"].includes(foodCat) ||
                    ["burger", "sandwich", "quick_bite", "wrap", "chicken"].includes(generalCat) ||
                    src.startsWith("fastfood/")
                );
            }

            if (cat === "drink") {
                return foodCat.includes("drink") || generalCat.includes("drink");
            }

            return foodCat.includes(cat) || generalCat.includes(cat) || cuisine.includes(cat);
        },
        buildFoodSubtitle(food) {
            const normalize = (value) => {
                if (value === null || value === undefined) {
                    return "";
                }
                return String(value).trim();
            };
            const toLabel = (value) => normalize(value)
                .split(/[_\s]+/)
                .filter(Boolean)
                .map((segment) => segment.charAt(0).toUpperCase() + segment.slice(1).toLowerCase())
                .join(" ");

            const parts = [];
            const veganByFlag = Number.parseInt(food.is_vegan, 10) === 1;
            const veganByLegacyType = normalize(food.food_type).toLowerCase() === "vegan";

            if (veganByFlag || veganByLegacyType) {
                parts.push("Vegan");
            } else if (normalize(food.meat_type)) {
                parts.push(toLabel(food.meat_type));
            } else if (normalize(food.food_type)) {
                parts.push(toLabel(food.food_type));
            }

            if (normalize(food.spice_level)) {
                parts.push(toLabel(food.spice_level));
            }

            if (normalize(food.cuisine_type)) {
                parts.push(toLabel(food.cuisine_type));
            } else if (normalize(food.category)) {
                parts.push(toLabel(food.category));
            } else if (normalize(food.food_category)) {
                parts.push(toLabel(food.food_category));
            }

            return parts
                .filter((value, index, allParts) => value && allParts.indexOf(value) === index)
                .slice(0, 3)
                .join(" | ");
        },

        async getRecommendations() {
            this.recommendationsLoading = true;
            try {
                const userId = this.user && this.user.user_id ? this.user.user_id : 0;
                const response = await axios.get(`/recommendations/${userId}?limit=6&minHistory=3&excludeCart=true`);
                this.recommendedFoods = Array.isArray(response.data) ? response.data : [];
            } catch (error) {
                console.log(error);
                this.recommendedFoods = [];
            } finally {
                this.recommendationsLoading = false;
            }
        },

        addItemByFood(foodId) {
            this.sendId = parseInt(foodId, 10);
            this.showQuickView = !this.showQuickView;
        },
        set(val) {
            this.pageNum = val;
        },
        next() {
            this.pageNum++;
        },
        previous() {
            this.pageNum--;
        },
        checkSale: function (food, statusArray) {
            if (statusArray.includes("Sale Off")) {
                if (parseFloat(food.food_discount) > 0) {
                    return true;
                }
                else {
                    return false;
                }
            }
            return true;
        },
        checkBest: function (food, statusArray) {
            if (statusArray.includes("Best Seller")) {
                if (food.food_status.includes("best seller")) {
                    return true;
                }
                else {
                    return false;
                }
            }
            return true;
        },
        checkOnl: function (food, statusArray) {
            if (statusArray.includes("Online Only")) {
                if (food.food_status.includes("online only")) {
                    return true;
                }
                else {
                    return false;
                }
            }
            return true;
        },
        checkSeason: function (food, statusArray) {
            if (statusArray.includes("Seasonal Dishes")) {
                if (food.food_status.includes("seasonal dishes")) {
                    return true;
                }
                else {
                    return false;
                }
            }
            return true;
        },
        checkNew: function (food, statusArray) {
            if (statusArray.includes("New Dishes")) {
                if (food.food_status.includes("new dishes")) {
                    return true;
                }
                else {
                    return false;
                }
            }
            return true;
        },
        evaluateStatus: function (food, statusArray) {
            this.pageNum = 0;
            if (statusArray.length != 0) {
                if (this.checkSale(food, statusArray) && this.checkBest(food, statusArray) && this.checkNew(food, statusArray) && this.checkSeason(food, statusArray) && this.checkOnl(food, statusArray)) {
                    return food;
                }
            }
            else {
                return food;
            }
        },
        evaluatePrice: function (food, priceRange) {
            this.pageNum = 0;
            var cal = parseFloat(food.food_price) - parseFloat(food.food_discount);
            if (priceRange == "1500,5000") {
                if (1500 <= cal && cal <= 5000) {
                    return food;
                }
            }
            else if (priceRange == "5000,10000") {
                if (5000 <= cal && cal <= 10000) {
                    return food;
                }
            }
            else if (priceRange == "10000,15000") {
                if (10000 <= cal && cal <= 15000) {
                    return food;
                }
            }
            else if (priceRange == "1500") {
                if (cal <= 1500) {
                    return food;
                }
            }
            else if (priceRange == "15000") {
                if (cal >= 15000) {
                    return food;
                }
            }
            else if (priceRange == "") {
                return food;
            }
        },
        filterFoodBtn: function (e) {
    this.pageNum = 0;
    if (this.foodObj.category != e.target.value && this.previousCategoryClicked != "") {
        this.previousCategoryClicked.target.style.background = "#27ae60";
    }
    this.foodObj.category = e.target.value;
    this.previousCategoryClicked = e;
    e.target.style.background = "#057835fa";
},
        filterStatusBtn: function (e) {
            this.pageNum = 0;
            if (this.foodObj.status.includes(e.target.value) == false) {
                this.foodObj.status.push(e.target.value);
                document.querySelector(`[for=${e.target.id}]`).style.background = "#057835fa";
                document.querySelector(`[for=${e.target.id}]`).style.color = "white";
                document.querySelector(`[for=${e.target.id}]`).querySelector(":scope > button").style.display = "block";
            }
        },
        filterPriceBtn: function (e) {
            this.pageNum = 0;
            this.foodObj.price = "";
            this.foodObj.price += e.target.value;
            document.querySelector(`[for=${e.target.id}]`).style.background = "#057835fa";
            document.querySelector(`[for=${e.target.id}]`).style.color = "white";
            document.querySelector(`[for=${e.target.id}]`).querySelector(":scope > button").style.display = "block";
            if (this.previousPriceClicked != "") {
                document.querySelector(`[for=${this.previousPriceClicked.target.id}]`).style.background = "inherit";
                document.querySelector(`[for=${this.previousPriceClicked.target.id}]`).style.color = "inherit";
                document.querySelector(`[for=${this.previousPriceClicked.target.id}]`).querySelector(":scope > button").style.display = "none";
            }
            this.previousPriceClicked = e;
        },
        filterTypeBtn: function (e) {
            this.pageNum = 0;
            this.foodObj.type = "";
            this.foodObj.type += e.target.value;
            document.querySelector(`[for=${e.target.id}]`).style.background = "#057835fa";
            document.querySelector(`[for=${e.target.id}]`).style.color = "white";
            document.querySelector(`[for=${e.target.id}]`).querySelector(":scope > button").style.display = "block";
            if (this.previousTypeClicked != "") {
                document.querySelector(`[for=${this.previousTypeClicked.target.id}]`).style.background = "inherit";
                document.querySelector(`[for=${this.previousTypeClicked.target.id}]`).style.color = "inherit";
                document.querySelector(`[for=${this.previousTypeClicked.target.id}]`).querySelector(":scope > button").style.display = "none";
            }
            this.previousTypeClicked = e;
        },
        unselectStatusBtn: function (e) {
            this.pageNum = 0;
            this.foodObj.status = this.foodObj.status.filter(function (a) { return a !== e.target.value; });
            e.target.parentNode.style.background = "inherit";
            e.target.parentNode.style.color = "inherit";
            e.target.parentNode.querySelector(":scope > button").style.display = "none";
        },
        unselectPriceBtn: function () {
            this.pageNum = 0;
            this.foodObj.price = "";
            document.querySelector(`[for=${this.previousPriceClicked.target.id}]`).style.background = "inherit";
            document.querySelector(`[for=${this.previousPriceClicked.target.id}]`).style.color = "inherit";
            document.querySelector(`[for=${this.previousPriceClicked.target.id}]`).querySelector(":scope > button").style.display = "none";
            this.previousPriceClicked = "";
        },
        unselectTypeBtn: function () {
            this.pageNum = 0;
            this.foodObj.type = "";
            document.querySelector(`[for=${this.previousTypeClicked.target.id}]`).style.background = "inherit";
            document.querySelector(`[for=${this.previousTypeClicked.target.id}]`).style.color = "inherit";
            document.querySelector(`[for=${this.previousTypeClicked.target.id}]`).querySelector(":scope > button").style.display = "none";
            this.previousTypeClicked = "";
        },
        addItem: function (index) {
            this.sendId = parseInt(this.currentPageItems[index].food_id);
            this.showQuickView = !this.showQuickView;
        },

        closeView: function () {
            this.showQuickView = !this.showQuickView;
        },

        displayFilterDrop: function () {
            let divControl1 = document.getElementsByClassName("filter-heading");
            let divControl2 = document.getElementsByClassName("filter-section");
            for (var i = 0; i < divControl1.length; i++) {
                if (this.showDropDown) {
                    divControl1[i].style.display = "none";
                    divControl2[i].style.display = "none";
                }
                else {
                    divControl1[i].style.display = "block";
                    divControl2[i].style.display = "block";
                }
            }
            this.showDropDown = !this.showDropDown;
        }

    },
    components: { QuickView }
};
</script>

